import sys; sys.path.insert(0, '_tools'); from spec import enrich
enrich('el-engano', 'C',
 [dict(t=1735, e=1790, titulo='Una iglesia de Natanaeles', txt='Yo vengo diciéndole a esta iglesia que va a ser un prototipo de Natanaeles, que vamos a dar de qué hablar, pero para bien. Que cuando la gente mire esta iglesia diga: «Yo quiero estar aquí. Algo tienen estos que no tienen los demás, algo le hicieron». Y eso se llama Espíritu Santo, del poder de la promesa que Dios tiene para nosotros. No ha terminado nada. Todo empieza hoy. Todas las cosas viejas pasaron; hoy son hechas nuevas.'),
  dict(t=3509, e=3560, titulo='Jacob, el engañador', txt='Si hubieran llamado a Jacob, no Israel, ¿cómo le hubieran dicho? A gran voz: «Jacob, tienes cara de engañador en la ficha». Y era engañador. Engañó a todos, hermano. Solo a Dios, no, pero a todos. […] Lo engañó en las lentejas también. […] Pero lo engañó y se quedó solo. Ah, eso de quedarse solo no es tan fácil, hermano.'),
  dict(t=3896, e=3945, titulo='El corazón es engañoso', txt='Jeremías 17:9: «Más engañoso que todo es el corazón». Por eso tenemos que tener mucho cuidado, y el Espíritu Santo, que nos guía a toda verdad, es el que te va a señalar el engaño. Porque hay cosas que parecen buenas, pero son malas, y malas que parecen buenas. Ten cuidado con engañarte con eso: la persona cree que está en la verdad y está equivocada. «Y sin remedio, ¿quién lo comprenderá?». Solo el Espíritu Santo.')],
 [dict(t=1655, txt='¿Qué dijo Jesús? «Sígueme». Entonces, sigue a Jesús y vas a ver.'),
  dict(t=2525, txt='Hermano, engañamos de muchas maneras, y el Señor lo que quiere es que seamos diáfanos, cristalinos, que haya un Natanael en usted.'),
  dict(t=4920, txt='Hay gente que ya no aguanta por estar engañando, engañando, engañando, pero hoy el Señor te hace libre en el nombre de Jesús.')],
 ['¿Qué significa para ti seguir a Jesús con una acción concreta, como el «ven y ve» que Felipe le dijo a Natanael?',
  '¿En qué cosas pequeñas de tu día hay una diferencia entre lo que dices ser y lo que haces?',
  'Si el Espíritu Santo te señalara hoy un engaño en tu corazón, ¿estarías dispuesto a escucharlo?'])
